import{_ as i,o as a,c as n,ai as t}from"./chunks/framework.BxxKhjs3.js";const l="/pub-blog/assets/image-20250116090935066.CZlSKbVj.png",e="/pub-blog/assets/image-20250116091157505.y7idt2Tc.png",p="/pub-blog/assets/image-20250116091237635.BfchN-ML.png",h="/pub-blog/assets/image-20250116095501501.DWWc8uOv.png",k="/pub-blog/assets/image-20250116095523881.rpcEvgTA.png",r="/pub-blog/assets/image-20250116095646627.cOqWt548.png",d="/pub-blog/assets/image-20250116095730657.CAiM5x9D.png",E="/pub-blog/assets/image-20250116100212297.aTng-z_X.png",o="/pub-blog/assets/image-20250116100026310.C6vVrVhj.png",g="/pub-blog/assets/image-20250116100343797.DwgByfdy.png",c="/pub-blog/assets/image-20250116100642788.ClZyIeP7.png",y="/pub-blog/assets/image-20250116100701709.KELNsNfV.png",u="/pub-blog/assets/image-20250116100720676.Bs8NfMXq.png",b="/pub-blog/assets/image-20250116100749650.CU2Hxcp_.png",F="/pub-blog/assets/image-20250116100943842.U2_iIq05.png",m="/pub-blog/assets/image-20250116105318813.DMlTps9b.png",C="/pub-blog/assets/image-20250116130255215.DNfQ1C3Y.png",B="/pub-blog/assets/image-20250116160900005._bA9aAbX.png",A="/pub-blog/assets/image-20250116160911750.CoSjlOF7.png",D="/pub-blog/assets/image-20250116161334518.DtpRJ7f0.png",f="/pub-blog/assets/image-20250116170856484.Bqw5yEnB.png",q="/pub-blog/assets/image-20250116170956502.CSkRwb6K.png",x="/pub-blog/assets/image-20250117001110198.mqlQq257.png",v="/pub-blog/assets/image-20250117001731385.CD2yhrgz.png",w="/pub-blog/assets/image-20250117011316637.D_bIMlB4.png",P="/pub-blog/assets/image-20250117201256407.CGh1qdWV.png",T="/pub-blog/assets/image-20250117203951021.CL1z1-5E.png",S="/pub-blog/assets/image-20250118233735515.IwkKQFCY.png",j="/pub-blog/assets/image-20250118235504943.CenHE6Ku.png",N="/pub-blog/assets/image-20250119000030512.DZ51owJN.png",O="/pub-blog/assets/image-20250119001021913.CJJSVvxh.png",_="/pub-blog/assets/image-20250119021913620.CHbtvNse.png",M="/pub-blog/assets/image-20250119022910282.C5R0cXit.png",G="/pub-blog/assets/image-20250119023215094.D4ZjAoie.png",I="/pub-blog/assets/image-20250208224404854.BEX4FGKm.png",$="/pub-blog/assets/image-20250208225612809.Lc1suQwl.png",U="/pub-blog/assets/image-20250208224438567.CXu23vXt.png",V="/pub-blog/assets/image-20250208225401478.BqBJBVzz.png",L="/pub-blog/assets/image-20250208231342642.BxPfZXGv.png",R="/pub-blog/assets/image-20250208231411534.fQxQul-4.png",H="/pub-blog/assets/image-20250208231500267.oDpf5CtQ.png",K="/pub-blog/assets/image-20250209095250827.CORyTjJU.png",J="/pub-blog/assets/image-20250209095502324.C3Z1oPUJ.png",Q="/pub-blog/assets/image-20250209104450026.BAGTU_62.png",W="/pub-blog/assets/image-20250209104513583.B6K_GXg2.png",Z="/pub-blog/assets/image-20250209104549805.BLQWkvpq.png",Y="/pub-blog/assets/image-20250209105304376.C3NRoL2I.png",z="/pub-blog/assets/image-20250209112440351.C2Cexefo.png",X="/pub-blog/assets/image-20250209112607971.3QQS7y8z.png",ss="/pub-blog/assets/image-20250209133623676.DMXuZ4PS.png",is="/pub-blog/assets/image-20250209133103645.BglyhYID.png",as="/pub-blog/assets/image-20250209133521557.BcYrOU7N.png",ns="/pub-blog/assets/image-20250209140233851.BjKl0tBE.png",Es=JSON.parse('{"title":"HarmonyOS Next 端云一体化完整教程","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOSNext 端云一体化/HarmonyOSNext 端云一体化完整版/HarmonyOSNext 端云一体化完整版.md","filePath":"鸿蒙开发技巧/HarmonyOSNext 端云一体化/HarmonyOSNext 端云一体化完整版/HarmonyOSNext 端云一体化完整版.md","lastUpdated":1769228137000,"__rawMarkdown":"# HarmonyOS Next 端云一体化完整教程\\n\\n## 目录\\n\\n1. [端云一体化基础](#端云一体化基础)\\n2. [云数据库操作](#云数据库操作)\\n3. [客户端操作云数据库](#客户端操作云数据库)\\n4. [数据库查询条件](#数据库查询条件)\\n5. [云存储操作](#云存储操作)\\n6. [云函数开发](#云函数开发)\\n\\n---\\n\\n## 端云一体化基础\\n\\n### 介绍\\n\\nCloud Foundation Kit（云开发服务）可以按需为应用提供云函数、云数据库、云存储等云端服务。应用运行所需的服务器和环境可以皆由云端平台提供，开发者只需关注应用的业务逻辑，而无需关心基础设施（例如：服务器、操作系统、容器等）。\\n\\nDevEco Studio 中还提供了[端云一体化开发](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/agc-harmonyos-clouddev-overview-V5)的开发体验，您可以基于统一的技术栈，高效、协同地完成端、云代码的编写、调试、编译和部署，极大提高构建 HarmonyOS 应用和元服务的效率。\\n\\n### 应用场景\\n\\n- **应用后端** 快速构建应用或者元服务的后端服务，从而大幅简化应用开发与运维相关的事务，快速完成应用的构建\\n- **计算密集型任务** 当应用中出现计算密集型任务时，可以在云端及时申请足够的算力来支撑任务的执行。当任务结束时，可以立即释放资源，避免浪费。\\n- **适配类应用** 通过 Cloud Foundation Kit 实现协议类型的转换，比如实现 IoT 中不同设备的协议适配。以及接入第三方平台，通过第三方平台提供的接口，实现业务的接入或者协作。\\n- **突发大量访问** 传统架构服务在某些特殊场景下，可能出现大量的访问。为保证业务高峰时，系统能稳定运行，一般需要购买高性能、昂贵的服务器，组建集群负载均衡。但是，当业务回落时，就导致了大量服务器的资源浪费。\\n\\n### 包含的资源\\n\\n端云一体主要包含的资源有\\n\\n- 云函数\\n- 云数据库\\n- 云存储\\n\\n### 适配的项目类型\\n\\n端云一体可以用在开发鸿蒙的**应用**或者是元服务上。因为考虑应用的上架需要软著+备案，而元服务的上架只需要备案。所以后续的教程中为了更加方便学习，我们会在元服务的环境下进行。\\n\\n### 学习流程\\n\\n稍后我们会延续着以下步骤，让大家可以尽可能的掌握端云一体的开发流程。\\n\\n![image-20250116090935066](assets/image-20250116090935066.png)\\n\\n1. AGC 平台新建元服务\\n2. DevEco Studio 新建对应的项目工程\\n3. 云函数的基本使用\\n4. 云数据库的基本使用\\n5. 云存储的基本使用\\n\\n### AGC 平台新建元服务\\n\\n在 AGC 平台上新建服务的具体步骤可以参考这个文章 [HarmonyOS Next 最新 元服务新建到上架全流程](https://juejin.cn/post/7441761663701041161)，这里就不再叙述了。\\n\\n### DevEco Studio 新建对应的项目工程\\n\\n本地在使用 DevEco Studio 新建工程时，需要新建的是端云一体化的元服务项目。\\n\\n![image-20250116091157505](assets/image-20250116091157505.png)\\n\\n此时，你的项目中会看到额外的云端相关的目录结构。\\n\\n![image-20250116091237635](assets/image-20250116091237635.png)\\n\\n> 特别需要注意的是，目前模拟器是不支持运行端云一体的项目的。所以为了方便测试，最好是具体**真机**。\\n\\n### 运行到真机\\n\\n![image-20250116095501501](assets/image-20250116095501501.png)\\n\\n- 测试下云函数\\n\\n![image-20250116095523881](assets/image-20250116095523881.png)\\n\\n- 测试下云数据库\\n\\n  > 还没有在云端配置云数据库，所以此时的测试是没有反应的。\\n\\n  ![image-20250116095646627](assets/image-20250116095646627.png)\\n\\n- 测试下云存储\\n\\n  ![image-20250116095730657](assets/image-20250116095730657.png)\\n\\n### 云端环境一览\\n\\n我们需要知道的是，在本地操作云端的资源时，本质上都是对云端的资源的一些操作。最终的操作成功与否，都会反映到真正的云端环境。\\n\\n我们登录 AGC 平台，然后找到对应的项目。_这里是元服务的名称，不是项目的名称，你的元服务是归属于某个项目的_\\n\\n![image-20250116100212297](assets/image-20250116100212297.png)\\n\\n#### 云函数一览\\n\\n云函数其实就是存放后端逻辑的部分。也是我们后期编写后端业务主要区域。\\n\\n![image-20250116100026310](assets/image-20250116100026310.png)\\n\\n#### 云数据库一览\\n\\n![image-20250116100343797](assets/image-20250116100343797.png)\\n\\n这里的字段解释如下\\n\\n| 字段     | 说明                                                                                         |\\n| -------- | -------------------------------------------------------------------------------------------- |\\n| 对象类型 | 表示你的数据中用到的实体的类型，比如用户、购物车都是不同的实体类型，也可以理解为你的数据表格 |\\n| 存储区   | 理解为数据库的名称，你可以在这里管理多个存储区-数据库                                        |\\n| 数据     | 你存储的实际的数据                                                                           |\\n\\n- 对象类型\\n\\n  ![image-20250116100642788](assets/image-20250116100642788.png)\\n\\n- 存储区\\n\\n  ![image-20250116100701709](assets/image-20250116100701709.png)\\n\\n- 数据\\n\\n  ![image-20250116100720676](assets/image-20250116100720676.png)\\n\\n#### 云存储一览\\n\\n云存储就是存放你物理文件的地方，比如图片、视频、音频等等。\\n\\n![image-20250116100749650](assets/image-20250116100749650.png)\\n\\n### DevEco Studio 中的云端资源\\n\\n小伙伴们应该还记得，我们在新建端云一体云服务的时候，本地工程中也是多了一个文件夹的。 `CloudProgram`\\n\\n![image-20250116100943842](assets/image-20250116100943842.png)\\n\\n它里面的主要目录结构如下。\\n\\n1. **clouddb** 存放数据库相关的文件\\n2. **cloudfunctions** 存放云函数相关的文件\\n3. **cloud-config.json** 存放云端环境相关的配置\\n\\n后期我们开发的思路可以是以下两种方式：\\n\\n1. 全部都在 AGC 平台上操作，如编写云函数逻辑代码、搭建数据库、数据表\\n2. **尽量都在本地 DevEco Studio 工具中编写云函数逻辑代码、调试代码、搭建数据库、数据集表**\\n\\n以上两种方式都可以。但是为了刚好的开发体验，我们是建议使用方式 2.\\n\\n---\\n\\n## 云数据库操作\\n\\n### 介绍\\n\\n云数据库是端云协同的数据库产品，具备端云数据协同管理、统一数据模型及丰富数据管理 API 接口等能力。它采用基于**对象模型** 的数据存储结构，数据以**对象（Object）** 形式存于不同存储区，每个对象为一条完整数据记录。 **对象类型（ObjectType）** 定义存储对象集合，不同对象类型对应不同数据结构。**存储区（Zone）** 是独立的数据存储区域，每个存储区的对象类型定义完全相同。\\n\\n### 学习流程\\n\\n我们会按照以下流程来进行学习。\\n\\n1. 新建存储区：也就是新建数据库\\n2. 创建对象类型：创建一个用于存储数据条目的对象类型。\\n3. 添加数据条目：在刚刚创建的对象类型内添加一条条数据，并配置数据所在的存储区。\\n4. 部署云数据库：数据成功添加后，您可以直接将该数据部署至 AGC 云端。您也可以等所有对象类型和数据条目开发完成后，再统一批量部署到 AGC 云端。\\n\\n### 存储区\\n\\n我们这里新建一个存储区 **Study** 用来存放稍后用到的数据。\\n\\n![image-20250116105318813](assets/image-20250116105318813.png)\\n\\n然后我们在 **DevEco Studio** 的 云端配置中指定存储区。\\n\\n`clouddb/db-config.json`\\n\\n```\\n{\\n\\t\\"defaultCloudDBZoneName\\": \\"Study\\", // 存储区的名称\\n\\t\\"defaultDataStorageLocation\\": \\"CN\\"\\n}\\n```\\n\\n### 创建对象类型\\n\\n#### 什么是创建对象类型\\n\\n创建对象类型可以理解为就是为我们的数据定义类型。类似于使用接口或者 class 来定义数据，但是这里操作的范围要更大。\\n\\n1. 定义基本的数据类型，如数字、字符串、布尔、日期时间等。\\n2. 定义字段的权限，因为这个对象类型本身是数据表，定义权限相当于设置了哪一类用户拥有哪些权限。如读取、编辑、新增、删除等\\n3. 定义索引，考虑数据量大需要比较方便的查找到要操作的数据，需要定义索引。\\n\\n比如，我们需要根据书籍数据来定义类型。 `Book`\\n\\n| 字段    | 类型    | 说明     |\\n| ------- | ------- | -------- |\\n| id      | number  | id       |\\n| name    | string  | 书名     |\\n| price   | number  | 价格     |\\n| publish | date    | 出版日期 |\\n| hot     | boolean | 是否热门 |\\n| cover   | string  | 封面     |\\n\\n#### 对象类型的规范\\n\\n新建 Book 对象类型文件\\n\\n![image-20250116130255215](assets/image-20250116130255215.png)\\n\\n这个对文件需要按照以下格式来编写。其中的字段的一些规范需要特别注意。\\n\\n```json\\n{\\n  \\"objectTypeName\\": 对象实体名称\\n  \\"fields\\": 对象中的属性\\n  \\"indexes\\": 索引\\n  \\"permissions\\" 权限\\n}\\n```\\n\\n##### objectTypeName\\n\\n表示实体对象的名称，我们这里可以是 `Book`\\n\\n```json\\n{\\n  \\"objectTypeName\\": \\"Book\\"\\n}\\n```\\n\\n##### fields\\n\\nfields 表示这个对象中属性的一些规则。\\n\\n| 参数             | 必选(M)/可选(O) | 说明                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    |\\n| :--------------- | :-------------- | :-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\\n| fieldName        | M               | 字段名称。输入要求具体如下：字段的名称长度必须大于或等于 1 个字符，小于或等于 30 个字符，只能包含以下 3 种类型，并且至少包含\\"字母\\"类型：字母（A-Z 或 a-z）数字（0-9）特殊字符：\\\\_字段名称必须以字母开头，以字母或者数字结尾。字段名称中不区分字母的大小写。修改对象类型时，支持删除字段。字段名称不允许使用系统保留字段名称： naturalbase_version、naturalbase_deleted、naturalbase_operationtype、naturalbase_creator、naturalbase_accesstime、naturalbase_operationtime、naturalbase_syncstatus、naturalbase_changedfieldsbitmap、naturalbase_lastmodifier、cmin、cmax、xmin、xmax、ctid、oid、tableoid、xc_node_id、tablebucketid、rowid。说明当前 Cloud Foundation Kit 暂不支持自增类型字段 IntAutoIncrement 或 LongAutoIncrement。 |\\n| fieldType        | M               | 字段的数据类型。当前支持的数据类型：String、Boolean、Byte、Short、Integer、Long、Float、Double、ByteArray、Text、Date、IntAutoIncrement（数字-自增）                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    |\\n| belongPrimaryKey | O               | 设置该字段是否为对象类型的主键，默认值为 false。至少设置一个字段为主键。支持设置复合主键，由多个字段组合成为主键，一个复合主键包含的字段小于等于 5 个，复合主键字段顺序与字段的顺序一致。数据类型为 ByteArray、Text、Date、Double、Float 和 Boolean 的字段不支持设置为主键。主键的值不允许更改。                                                                                                                                                                                                                                                                                                                                                                                                                                        |\\n| notNull          | O               | 设置字段值是否为非空，默认值为 false。数据类型为 ByteArray 和 Date 的字段不支持设置为非空。主键默认非空，且不允许更改。设置为非空的字段不支持加密和敏感。                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               |\\n| isNeedEncrypt    | O               | 设置字段是否需要加密，开启全程加密数据管理功能，默认值为 false。选择加密后，该字段对应的数据会加密存储在存储区中。主键字段不支持加密。加密的字段不支持设置为非空。加密的字段不支持设置为敏感字段。一个对象类型中包含的加密字段和敏感字段的总数需小于或等于 5 个。字段设置为加密后，不支持导出该字段的数据值。数据类型为 ByteArray、Text 的字段不支持加密。对象类型创建成功后，不支持修改加密属性。                                                                                                                                                                                                                                                                                                                                      |\\n| isSensitive      | O               | 设置字段是否为敏感字段，默认值为 false。选择敏感后，该字段对应的数据会加密存储在存储区中。敏感字段不支持设置为主键。敏感字段不支持设置为非空。敏感字段不支持设置为加密。敏感字段不支持设置为默认值。对象类型创建成功后，不支持修改敏感属性。仅支持数据类型为 Byte、Short、Integer、Long、Float、Double、String 和 Date 的字段设置为敏感字段。敏感字段不支持设置为索引。一个对象类型中包含的加密字段和敏感字段的总数需小于或等于 5 个。                                                                                                                                                                                                                                                                                                  |\\n| defaultValue     | O               | 字段为非空时，必须设置默认值。主键不支持设置默认值。加密字段和敏感字段不支持设置默认值。数据类型为 ByteArray、Date 不支持为其设置默认值。数据类型为 Text 的字段设置默认值时，默认值的长度小于或等于 200 个字符。                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        |\\n\\n按照我们想要的**书籍**的规定。可以这样\\n\\n| fieldName | fieldType        | belongPrimaryKey |\\n| --------- | ---------------- | ---------------- |\\n| id        | IntAutoIncrement | true             |\\n| name      | String           | -                |\\n| price     | Double           | -                |\\n| publish   | Date             | -                |\\n| hot       | Boolean          | -                |\\n| cover     | String           | -                |\\n\\n```json\\n{\\n  \\"objectTypeName\\": \\"Book\\",\\n  \\"fields\\": [\\n    {\\n      \\"fieldName\\": \\"id\\",\\n      \\"fieldType\\": \\"IntAutoIncrement\\",\\n      \\"belongPrimaryKey\\": true,\\n      \\"notNull\\": true\\n    },\\n    {\\n      \\"fieldName\\": \\"name\\",\\n      \\"fieldType\\": \\"String\\"\\n    },\\n    {\\n      \\"fieldName\\": \\"price\\",\\n      \\"fieldType\\": \\"Double\\"\\n    },\\n    {\\n      \\"fieldName\\": \\"publish\\",\\n      \\"fieldType\\": \\"Date\\"\\n    },\\n    {\\n      \\"fieldName\\": \\"hot\\",\\n      \\"fieldType\\": \\"Boolean\\"\\n    },\\n    {\\n      \\"fieldName\\": \\"cover\\",\\n      \\"fieldType\\": \\"String\\"\\n    }\\n  ]\\n}\\n```\\n\\n##### indexes\\n\\n在**indexes**中为该对象类型配置索引、索引包含的字段、以及索引包含的字段的排序方式。\\n\\n| 参数                  | 必选(M)/可选(O) | 说明                                                                                                                                                                                                                                                                                                                                                                                                                       |\\n| :-------------------- | :-------------- | :------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\\n| indexName             | M               | 索引名称。输入要求具体如下：索引的名称长度必须大于或等于 1 个字符，小于或等于 30 个字符，只能包含以下 3 种类型，并且至少包含\\"字母\\"类型：字母（A-Z 或 a-z）数字（0-9）特殊字符：\\\\_索引名称必须以字母开头。索引名称中不区分字母的大小写。修改对象类型时，仅支持新增或者删除索引。当删除索引后，本次提交前不允许新增同名索引。每个对象类型可以设置小于或等于 16 个索引。数据类型为 ByteArray 和 Text 的字段不支持设置为索引。 |\\n| indexList > fieldName | M               | 索引包含的字段。支持设置组合索引，由多个字段组合成为索引，一个组合索引包含的字段不超过 5 个。                                                                                                                                                                                                                                                                                                                              |\\n| indexList > sortType  | M               | 索引包含的字段的排序方式，支持 ASC 升序或 DESC 降序。                                                                                                                                                                                                                                                                                                                                                                      |\\n\\n这里我们为书籍的 id 和书籍的名称提供索引。\\n\\n```json\\n{\\n  \\"indexes\\": [\\n    {\\n      \\"indexName\\": \\"id_Index\\",\\n      \\"indexList\\": [\\n        {\\n          \\"fieldName\\": \\"id\\",\\n          \\"sortType\\": \\"ASC\\"\\n        }\\n      ]\\n    },\\n    {\\n      \\"indexName\\": \\"price_Index\\",\\n      \\"indexList\\": [\\n        {\\n          \\"fieldName\\": \\"price\\",\\n          \\"sortType\\": \\"DESC\\"\\n        }\\n      ]\\n    }\\n  ]\\n}\\n```\\n\\n##### permissions\\n\\n**permissions** 字段用来设置该数据表的操作权限的。\\n\\n目前提供的角色和权限有以下分类。\\n\\n| 参数   | 必选(M)/可选(O) | 说明                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 |\\n| :----- | :-------------- | :----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\\n| role   | M               | 用户角色，包括：World：代表所有用户，包含认证和非认证用户。该角色默认拥有 Read 权限，可自定义配置 Upsert 和 Delete 权限。但是，不建议将 Upsert 和 Delete 权限配置给所有人角色。当对象类型中设置了加密字段之后，表示开启全程加密功能，此时所有人角色将不会拥有 Read、Upsert 和 Delete 权限，且不允许修改。Authenticated：经过 AGC 登录认证的用户。该角色默认拥有 Read 权限，可自定义配置 Upsert 和 Delete 权限。当对象类型中设置了加密字段之后，表示开启全程加密功能，此时认证用户角色将不会拥有 Read、Upsert 和 Delete 权限，且不允许修改。Creator：经过认证的数据创建用户。该角色默认拥有所有权限，且可自定义配置所有权限。每条数据都有其对应的数据创建人（即应用用户），每个数据创建者仅可以 Upsert 或者 Delete 自己创建的数据，不能 Upsert 或者 Delete 他人创建的数据。数据创建者的信息保存在数据记录的系统表中。Administrator：应用开发者，主要是指通过 AGC 控制台或 FaaS（Function as a Service，函数即服务）侧访问云数据库的角色。该角色默认拥有所有权限，且可自定义配置所有权限。Administrator 可以管理并配置其他角色的权限。 |\\n| rights | M               | 授予角色的权限，包括 Read、Upsert（包含新增和修改）和 Delete 权限。                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  |\\n\\n接下来，我们为 这些角色设置以下的权限。\\n\\n| 角色          | Read | Upsert | Delete |\\n| :------------ | :--- | :----- | :----- |\\n| World         | √    | –      | –      |\\n| Authenticated | √    | √      | –      |\\n| Creator       | √    | √      | √      |\\n| Administrator | √    | √      | √      |\\n\\n代码如下：\\n\\n```json\\n{\\n  \\"permissions\\": [\\n    {\\n      \\"role\\": \\"World\\",\\n      \\"rights\\": [\\"Read\\"]\\n    },\\n    {\\n      \\"role\\": \\"Authenticated\\",\\n      \\"rights\\": [\\"Read\\", \\"Upsert\\"]\\n    },\\n    {\\n      \\"role\\": \\"Creator\\",\\n      \\"rights\\": [\\"Read\\", \\"Upsert\\", \\"Delete\\"]\\n    },\\n    {\\n      \\"role\\": \\"Administrator\\",\\n      \\"rights\\": [\\"Read\\", \\"Upsert\\", \\"Delete\\"]\\n    }\\n  ]\\n}\\n```\\n\\n### 创建数据条目\\n\\n我们搭建好了对象类型，现在可以根据它来插入数据了。\\n\\n1. 新建数据文件\\n\\n   ![image-20250116160900005](assets/image-20250116160900005.png)\\n\\n   ***\\n\\n   ![image-20250116160911750](assets/image-20250116160911750.png)\\n\\n2. 插入数据 这里可以看到一些基本数据\\n\\n   ```json\\n   {\\n     \\"cloudDBZoneName\\": \\"Study\\",\\n     \\"objectTypeName\\": \\"Book\\",\\n     \\"objects\\": [\\n       {\\n         \\"id\\": 1,\\n         \\"name\\": \\"string1\\",\\n         \\"price\\": 10.5,\\n         \\"publish\\": 1737014949576,\\n         \\"hot\\": true,\\n         \\"cover\\": \\"string1\\"\\n       },\\n       {\\n         \\"id\\": 2,\\n         \\"name\\": \\"string2\\",\\n         \\"price\\": 20.5,\\n         \\"publish\\": 1737014949576,\\n         \\"hot\\": false,\\n         \\"cover\\": \\"string2\\"\\n       }\\n     ]\\n   }\\n   ```\\n\\n   字段解释\\n\\n   - **cloudDBZoneName**：配置存储区名称。\\n   - **objects**：配置当前对象类型中所有字段的值，即写入数据。一个对象（object）即为一条数据，您可以通过新建一个对象（object）来为字段赋新值，也可以修改某个对象（object）下字段的值（主键或加密字段的值不支持修改）\\n\\n### 部署云数据库\\n\\n刚才我们都是在本地搭建的数据库，现在我们需要将这些数据同步到 AGC 平台的数据库上。\\n\\n部署的方式也很简单\\n\\n1. 部署\\n\\n![image-20250116161334518](assets/image-20250116161334518.png)\\n\\n2. 成本\\n\\n![image-20250116170856484](assets/image-20250116170856484.png)\\n\\n3. 刷新 AGC 平台上的数据库\\n\\n   ![image-20250116170956502](assets/image-20250116170956502.png)\\n\\n---\\n\\n## 客户端操作云数据库\\n\\n上一章我们主要讲解了如何新建数据库、新建数据表已经部署数据库。这一章主要学习如何对数据库、数据表进行 CRUD 的操作。\\n\\n### 操作数据库的方式\\n\\n我们操作数据库的方式一共有 4 种。\\n\\n1. 可视化 - AGC 平台上直接编辑数据\\n2. 可视化 - DevEco Studio 中直接编辑数据\\n3. **编程 - 客户端通过代码的方式操作数据**\\n4. **编程 - 云函数通过代码的方式操作数据**\\n\\n方式 1、2 都是为了让开发人员简单、方便管理数据。但是实际的业务场景中，我们更多要关注的是 3、4 的方式。那么本章主要讲的是 **方式 3-客户端通过代码的方式操作数据** 。后续再讲到云函数的时候再来补充**方式 4。**\\n\\n### 生成客户端-数据模型\\n\\n先解释下这个功能是做什么的。因为我们的目标是要在 客户端来查询数据库的数据，那必不可少需要在客户端中定义数据表实体的类型。然后 **DevEco Studio** 提供了比较便捷的根据数据实体生成客户端-数据模型。\\n\\n![image-20250117001110198](assets/image-20250117001110198.png)\\n\\n> 我这里红色的提示是因为我之前已经生成过了，所以提示是否覆盖。\\n\\n成功后边得到如下内容：`entry/src/main/ets/common/types/Book.ts`\\n\\n```typescript\\n/*\\n * Copyright (c) Huawei Technologies Co., Ltd. 2024-2024. All rights reserved.\\n * Generated by the CloudDB ObjectType compiler. DO NOT EDIT!\\n */\\nimport { cloudDatabase } from \\"@kit.CloudFoundationKit\\";\\n\\nclass Book extends cloudDatabase.DatabaseObject {\\n  id: number;\\n  name: string;\\n  price: number;\\n  publish: Date;\\n  hot: boolean;\\n  cover: string;\\n\\n  naturalbase_ClassName(): string {\\n    return \\"Book\\";\\n  }\\n}\\n\\nexport { Book };\\n```\\n\\n### 简单使用\\n\\n接下来我们就可以进入客户端查询数据库的步骤了。\\n\\n1. 首先我们需要创建一个数据库示例，每一个存储区就是一个数据库 `cloudDatabase.DatabaseZone`\\n2. 然后指定查询条件，比如全部查询、查询 id 等于 1 等等 `condition`\\n3. 进行查询，接收返回的数据\\n\\n```jsx\\nimport { cloudDatabase } from \'@kit.CloudFoundationKit\';\\nimport { Book } from \'../common/types/Book\';\\nimport { promptAction } from \'@kit.ArkUI\';\\n\\n@Entry\\n@Component\\nstruct PageDB {\\n  // 数据库实例，初始化时为 undefined\\n  agcDataBase: cloudDatabase.DatabaseZone | undefined = undefined;\\n  // 查询条件实例，初始化时为 undefined\\n  condition: cloudDatabase.DatabaseQuery<cloudDatabase.DatabaseObject> | undefined = undefined;\\n  // 初始化数据库连接的方法\\n  fn1 = () => {\\n    this.agcDataBase = cloudDatabase.zone(\'Study\');\\n    promptAction.showToast({ message: `初始化成功` });\\n  }\\n  // 查询数据库的方法\\n  fn2 = async () => {\\n    try {\\n      // 创建查询条件实例\\n      this.condition = new cloudDatabase.DatabaseQuery(Book);\\n      // 设置查询结果的最大数量为 10\\n      this.condition.limit(10);\\n      // 执行查询并获取结果\\n      const resultArray = await this.agcDataBase?.query(this.condition);\\n      // 显示查询结果\\n      AlertDialog.show({ message: JSON.stringify(resultArray, null, 2) });\\n    } catch (e) {\\n      promptAction.showToast({ message: `${e.message} ${e.code}` });\\n      console.error(e.message, e.code);\\n    }\\n  }\\n\\n  build() {\\n    Column({ space: 10 }) {\\n      Button(\\"初始化1\\")\\n        .onClick(this.fn1)\\n\\n      Button(\\"查询2\\")\\n        .onClick(this.fn2)\\n    }\\n    .height(\'100%\')\\n    .width(\'100%\')\\n  }\\n}\\n```\\n\\n![image-20250117001731385](assets/image-20250117001731385.png)\\n\\n### 对数据表的操作\\n\\n端云一体提供了基本的对数据表的操作。主要分成以下几种\\n\\n| 操作类型       | 说明         |\\n| -------------- | ------------ |\\n| query          | 查询         |\\n| upsert         | 新增或者编辑 |\\n| delete         | 删除         |\\n| calculateQuery | 计算         |\\n\\n#### query\\n\\n就是查询，上面的示例中已经使用过了。\\n\\n#### upsert - 新增\\n\\n现在主要演示 使用 **upsert** 实现新增\\n\\n**upsert** 方法可以接收一个或者多个数据实体。如果该数据之前不存在，这时的 upsert 表示新增，反之表示更新。\\n\\n操作成功后，会返回成功影响了的数据的数量。\\n\\n比如新增：\\n\\n```jsx\\nfn3 = async () => {\\n  try {\\n    const book = new Book();\\n    book.id = parseInt(Date.now().toString().slice(0, 6)); // 正常应该是自增的，但是这个自增会出bug\\n    book.name = \\"book\\";\\n    book.price = 99;\\n    book.publish = new Date();\\n    book.hot = true;\\n    book.cover = \\"xxxx\\";\\n    const res = await this.agcDataBase?.upsert(book);\\n    AlertDialog.show({ message: `新增成了${res}条` });\\n  } catch (e) {\\n    promptAction.showToast({ message: `${e.message} ${e.code}` });\\n    console.error(e.message, e.code);\\n  }\\n};\\n\\nButton(\\"新增3\\").onClick(this.fn3);\\n```\\n\\n![image-20250117011316637](assets/image-20250117011316637.png)\\n\\n需要注意的是：我们当前的角色是 `World`，此时是没有 新增、编辑、删除权限的。所以为了方便操作，可以修改调整权限\\n\\n> clouddb/objecttype/Book.json\\n\\n```json\\n    {\\n      \\"role\\": \\"World\\",\\n      \\"rights\\": [\\n        \\"Read\\",\\n        \\"Upsert\\",\\n        \\"Delete\\"\\n      ]\\n    },\\n```\\n\\n当数据表信息发生了修改时，需要在 AGC 平台上删除之前的数据区+数据表。然后重新部署。\\n\\n#### upsert - 编辑\\n\\n这里我们可以根据 id 来编辑一下数据。 数据库里面存放着**id：10** 的数据，我们就来修改它。\\n\\n![image-20250117201256407](assets/image-20250117201256407.png)\\n\\n```jsx\\nfn4 = async () => {\\n  try {\\n    const book = new Book();\\n    //  固定修改id为10的数据\\n    book.id = 10;\\n    book.name = \\"更新book\\";\\n    book.price = 999;\\n    book.publish = new Date();\\n    book.hot = true;\\n    book.cover = \\"更新 xxxx\\";\\n\\n    const res = await this.agcDataBase?.upsert(book); // 因为数据 id已经存在，所以此时是编辑\\n    AlertDialog.show({ message: `编辑成功${res}条` });\\n  } catch (e) {\\n    promptAction.showToast({ message: `${e.message} ${e.code}` });\\n    console.error(e.message, e.code);\\n  }\\n};\\n\\nButton(\\"更新4\\").onClick(this.fn4);\\n```\\n\\n#### delete - 删除\\n\\n执行删除 delete 方法时，也是需要传入一个或者多个删除的元素。\\n\\n我们这里就可以根据 id：10 的元素执行删除。\\n\\n```jsx\\nfn5 = async () => {\\n  try {\\n    const book = new Book();\\n    //  固定修改id为10的数据\\n    book.id = 10;\\n    const res = await this.agcDataBase?.delete(book); // 因为数据 id已经存在，所以此时是编辑\\n    AlertDialog.show({ message: `删除成功${res}条` });\\n  } catch (e) {\\n    promptAction.showToast({ message: `${e.message} ${e.code}` });\\n    console.error(e.message, e.code);\\n  }\\n};\\n\\nButton(\\"删除5\\").onClick(this.fn5);\\n```\\n\\n#### calculateQuery - 计算\\n\\n`calculateQuery` 从数据库中查询符合条件的数据，并对指定字段进行算术计算。主要提供了以下的计算功能。\\n\\n| 名称    | 值  | 说明           |\\n| :------ | :-- | :------------- |\\n| AVERAGE | 0   | 计算平均数。   |\\n| SUM     | 1   | 计算总和。     |\\n| MAXIMUM | 2   | 计算最大值。   |\\n| MINIMUM | 3   | 计算最小值。   |\\n| COUNT   | 4   | 计算记录总数。 |\\n\\n![image-20250117203951021](assets/image-20250117203951021.png)\\n\\n```jsx\\nfn6 = async () => {\\n  try {\\n    // 创建查询条件实例\\n    this.condition = new cloudDatabase.DatabaseQuery(Book);\\n    // 设置查询结果的最大数量为 10\\n    this.condition.limit(10);\\n    // 执行查询并获取结果\\n    const resultArray = await this.agcDataBase?.calculateQuery(\\n      this.condition,\\n      \\"price\\",\\n      cloudDatabase.QueryCalculate.SUM\\n    );\\n    // 显示查询结果\\n    AlertDialog.show({ message: JSON.stringify(resultArray, null, 2) });\\n  } catch (e) {\\n    promptAction.showToast({ message: `${e.message} ${e.code}` });\\n    console.error(e.message, e.code);\\n  }\\n};\\n\\nButton(\\"计算6 总价格\\").onClick(this.fn6);\\n```\\n\\n---\\n\\n## 数据库查询条件\\n\\n在上一章节我们讲了数据库数据表的一些基本操作。如query、upsert、delete和calculateQuery。这一章节主要来讲解各种查询条件操作。如 查询班级年龄大于30的同学等。\\n\\n### 查询条件解释\\n\\n> 谓词，用来代替或者展示其客体性质、特征或者客体之间关系的[词项](https://baike.baidu.com/item/词项/861117?fromModule=lemma_inlink)。\\n\\n这些查询条件在端云一体中解释中叫做**谓词**。云数据库中提供丰富的谓词查询来构建查询条件。根据谓词查询方法构造自己的DatabaseQuery对象。\\n\\n### 查询条件谓词一览\\n\\n| 关键字               | 说明                                                         |\\n| -------------------- | ------------------------------------------------------------ |\\n| equalTo              | 表示等于的条件判断，用于查询中筛选出与指定值相等的数据       |\\n| notEqualTo           | 表示不等于的条件判断，筛选出与指定值不相等的数据             |\\n| beginsWith           | 表示以某个值开头，用于查询开头匹配特定字符串的数据           |\\n| endsWith             | 表示以某个值结尾，用于查询结尾匹配特定字符串的数据           |\\n| contains             | 表示包含某个值，用于查询包含特定字符串的数据                 |\\n| greaterThan          | 表示大于，用于数值类型数据的比较，筛选出大于指定值的数据     |\\n| greaterThanOrEqualTo | 表示大于或等于，筛选出大于或等于指定值的数据                 |\\n| lessThan             | 表示小于，用于数值类型数据的比较，筛选出小于指定值的数据     |\\n| lessThanOrEqualTo    | 表示小于或等于，筛选出小于或等于指定值的数据                 |\\n| in                   | 用于判断某个值是否在指定的集合内，常用于查询符合多个值中某一个的数据 |\\n| isNull               | 用于判断某个字段是否为空值                                   |\\n| isNotNull            | 用于判断某个字段是否不为空值                                 |\\n| orderByAsc           | 按升序排列，用于对查询结果按照指定字段进行从小到大的排序     |\\n| orderByDesc          | 按降序排列，用于对查询结果按照指定字段进行从大到小的排序     |\\n| limit                | 限制查询结果返回的数量                                       |\\n| beginGroup           | 开始一个逻辑分组，用于将多个条件组合在一起作为一个逻辑单元   |\\n| endGroup             | 结束一个逻辑分组                                             |\\n| or                   | 逻辑或，用于连接多个条件，只要其中一个条件满足则整个逻辑表达式为真 |\\n| and                  | 逻辑与，用于连接多个条件，只有所有条件都满足时整个逻辑表达式才为真 |\\n\\n### 谓词使用示例\\n\\n#### equalTo 查询id为20的数据\\n\\n```typescript\\nthis.condition.equalTo(\\"id\\", 20)\\n```\\n\\n#### notEqualTo 查询id不等于20的数据\\n\\n```typescript\\nthis.condition.notEqualTo(\\"id\\", 20)\\n```\\n\\n#### beginsWith 查询name字段以b开头的数据\\n\\n```typescript\\nthis.condition.beginsWith(\\"name\\", \\"b\\")\\n```\\n\\n#### endsWith 查询name字段以k结尾的数据\\n\\n```typescript\\nthis.condition.endsWith(\\"name\\", \\"k\\")\\n```\\n\\n#### contains 查询name字段包含k的数据\\n\\n```typescript\\nthis.condition.contains(\\"name\\", \\"k\\")\\n```\\n\\n#### greaterThan 查询price字段大于30的数据\\n\\n```typescript\\nthis.condition.greaterThan(\\"price\\", 30)\\n```\\n\\n#### greaterThanOrEqualTo 查询price字段大于或者等于30的数据\\n\\n```typescript\\nthis.condition.greaterThanOrEqualTo(\\"price\\", 30)\\n```\\n\\n#### lessThan 查询price字段小于30的数据\\n\\n```typescript\\nthis.condition.lessThan(\\"price\\", 30)\\n```\\n\\n#### lessThanOrEqualTo 查询price字段小于或者等于30的数据\\n\\n```typescript\\nthis.condition.lessThanOrEqualTo(\\"price\\", 30)\\n```\\n\\n#### in 查询name字段包含在[\\"book\\",\\"aaaa\\",\\"bbbb\\"]的中数据\\n\\n```typescript\\nthis.condition.in(\\"name\\", [\\"book\\", \\"aaaa\\", \\"bbbb\\"])\\n```\\n\\n#### isNull 查询name字段是否为null\\n\\n```typescript\\nthis.condition.isNull(\\"name\\")\\n```\\n\\n#### isNotNull 查询name字段是否非null\\n\\n```typescript\\nthis.condition.isNotNull(\\"name\\")\\n```\\n\\n#### orderByAsc 根据id，进行升序\\n\\n```typescript\\nthis.condition.orderByAsc(\\"id\\")\\n```\\n\\n#### orderByDesc 根据id，进行降序\\n\\n```typescript\\nthis.condition.orderByDesc(\\"id\\")\\n```\\n\\n#### limit 查询2条数据，从第1条开始\\n\\n```typescript\\nthis.condition.limit(2, 1)\\n```\\n\\n#### or 逻辑或，查询name=book 或者 price>30的数据\\n\\n```typescript\\nthis.condition.equalTo(\\"name\\", \\"book\\").or().greaterThan(\'price\', 30)\\n```\\n\\n#### and 逻辑与，查询name=book123 并且 price>30的数据\\n\\n```typescript\\nthis.condition.equalTo(\\"name\\", \\"book123\\").and().greaterThan(\'price\', 30)\\n```\\n\\n#### beginGroup 和 endGroup 表示一对逻辑分组\\n\\n```typescript\\n // 条件1：   name=book并且price>30\\n\\n  // 条件2：   id=20或者price>30\\n\\n  // 需求： 查询 条件1 和 条件2 同时满足的数据\\n  this.condition\\n    .beginGroup()\\n    .equalTo(\'name\', 30)\\n    .and()\\n    .greaterThan(\'price\', 30)\\n    .endGroup()\\n    .and()\\n    .beginGroup()\\n    .equalTo(\'id\', 20)\\n    .or()\\n    .greaterThan(\'price\', 30)\\n    .endGroup();\\n```\\n\\n### 加强\\n\\n上面的谓词，也是根据实际语义搭配一起使用。比如：查询name=book的前2条数据\\n\\n---\\n\\n## 云存储操作\\n\\n上一章节我们主要讲解了查询条件-谓词的基本使用技巧。这一章我们主要来讲解下**客户端操作云存储。**\\n\\n### 云存储介绍\\n\\n云储存就是提供了一个可以存储物理文件的云端环境，比如存储图片、视频、音乐等，同时提供了的客户端操作云存储、云函数操作云存储的能力。我们这里主要讲解**客户端操作存储**，后续会讲解云函数操作云存储。\\n\\n### 云存储的计费策略\\n\\n#### 免费配额\\n\\n开通云存储服务后，华为供了免费额度以供试用，具体的配额明细如下。\\n\\n| 计费项               | 详细说明                                                     | 免费配额                                                     |\\n| :------------------- | :----------------------------------------------------------- | :----------------------------------------------------------- |\\n| 存储                 | 存储数据的容量，以小时为统计周期，UTC时间整点结算，单位为GB。 | 5GB注意\\"存储\\"为按月计费，而非一次性计费。如果您使用的存储容量每月都超过免费配额，您每月都需支付相应的超额费用。例如，本月您使用了6GB存储容量，则本月您需支付1GB的超额费用。如果下个月您服务的存储容量为7GB，下个月您仍需支付2GB的超额费用。 |\\n| 网络出站流量         | 公网流出流量，即通过互联网从云存储下载数据产生的流量。       | 1GB/天                                                       |\\n| 上传操作次数         | 上传接口请求次数。                                           | 20,000/天                                                    |\\n| 下载操作次数         | 下载接口请求次数。                                           | 50,000/天                                                    |\\n| 每个项目多个存储实例 | 单个项目支持创建多个存储实例。                               | **免费档不支持此功能**                                       |\\n\\n> 以某工具类APP为例，月新增下载量近1w，云存储提供的免费配额完全能支撑APP日常的调用。\\n\\n#### 升级到按量付费档\\n\\n当统计周期内的免费配额即将用尽时，您可以选择升级到按量付费档，以继续使用服务。或者，您也可以等到下个统计周期再使用云存储服务，在此之前服务将不再可用。\\n\\n云存储按量付费价格如下表所示，套餐升级操作请参见[升级到付费档](https://developer.huawei.com/consumer/cn/doc/development/AppGallery-connect-Guides/agc-service-billing-0000001058092595#section1337763420106)。\\n\\n| 计费项               | 详细说明                                                     | 按量付费价格         |\\n| :------------------- | :----------------------------------------------------------- | :------------------- |\\n| 存储                 | 存储数据的容量，以小时为统计周期，UTC时间整点结算，单位为GB。 | CNY 0.1679/GB        |\\n| 网络出站流量         | 公网流出流量，即通过互联网从云存储下载数据产生的流量。       | CNY 0.7751/GB        |\\n| 上传操作次数         | 上传接口请求次数。                                           | CNY 0.323/10,000     |\\n| 下载操作次数         | 下载接口请求次数。                                           | CNY 0.0258/10,000    |\\n| 每个项目多个存储实例 | 单个项目支持创建多个存储实例。                               | 按量付费档支持此功能 |\\n\\n### 云存储核心功能\\n\\n客户端操作存储的核心功能主要有以下。\\n\\n- 上传文件到云端\\n- 查看云端文件列表\\n- 查看云端文件元数据\\n- 设置云端文件数据\\n- 获取云端文件下载地址\\n- 下载云端文件到本地\\n- 删除云端文件\\n\\n接下来我们便开始对云存储进行操作。\\n\\n### 准备环境\\n\\n#### 开通云存储\\n\\n我们需要提前在AGC平台上开通云存储环境。\\n\\n![image-20250118233735515](assets/image-20250118233735515.png)\\n\\n我们可以看到，这个的云存储的实例名称为 **default-bucket-xxxx**\\n\\n#### 初始化云存储实例\\n\\n因为后期要操作云存储都需要用到云存储实例。所以需要初始化好。\\n\\n##### 使用默认云存储实例\\n\\n```typescript\\n bucket: cloudStorage.StorageBucket = cloudStorage.bucket(); // 获取默认的存储实例\\n```\\n\\n##### 指定云存储实例\\n\\n```typescript\\n bucket: cloudStorage.StorageBucket = cloudStorage.bucket(\\"default-bucket-xxxx\\"); // 获取默认的存储实例\\n```\\n\\n### 上传文件到云端\\n\\n上传文件到云端只能调用[StorageBucket.uploadFile](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/cloudfoundation-cloudstorage-V5#section2105131521913)方法，但是该方法要求上传的文件路径必须存放在**context.cacheDir**目录下。因此需要先提前做好这个处理。\\n\\n**步骤：**\\n\\n1. 选择待上传的文件，下方示例代码中使用[photoAccessHelper.PhotoViewPicker](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/js-apis-photoaccesshelper-V5#photoviewpicker)指定需要上传的文件。\\n2. 将待上传的文件复制到context.cacheDir目录下。\\n3. 调用[StorageBucket.uploadFile](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/cloudfoundation-cloudstorage-V5#section2105131521913)接口创建上传任务，监听上传任务的progress、completed、failed等事件。\\n4. 启动上传任务。\\n\\n> uploadFile在上传文件时，还支持上传自定义的标准的http头部信息。具体可以查看API说明\\n\\n**示例代码：**\\n\\n```jsx\\nfn8 = async () => {\\n    // 使用photoAccessHelper选择指定的文件\\n    let photoSelectOptions = new photoAccessHelper.PhotoSelectOptions();\\n    // 设置媒体文件类型为图像\\n    photoSelectOptions.MIMEType = photoAccessHelper.PhotoViewMIMETypes.IMAGE_TYPE;\\n    // 设置选择媒体文件的最大数目为1\\n    photoSelectOptions.maxSelectNumber = 1;\\n    let photoViewPicker = new photoAccessHelper.PhotoViewPicker();\\n    // 调用select方法选择图片，并处理选择结果\\n    photoViewPicker.select(photoSelectOptions).then((photoSelectResult: photoAccessHelper.PhotoSelectResult) => {\\n      // 获取选中文件的URI\\n      let fileUri = photoSelectResult.photoUris[0];\\n      console.info(`pick file ${fileUri}`);\\n      // 提取文件名\\n      let fileName = fileUri.split(\'/\').pop() as string;\\n      console.info(`file name ${fileName}`);\\n      // 创建缓存文件名，以当前时间戳和原文件名组合\\n      let cacheFile = `${Date.now()}_${fileName}`;\\n      console.info(`cacheFile ${cacheFile}`);\\n      // 拼接缓存文件路径\\n      let cacheFilePath = getContext().cacheDir + \'/\' + cacheFile;\\n\\n      // 将选中文件复制到缓存目录下，文件名为cacheFile\\n      try {\\n        // 打开源文件\\n        let srcFile = fs.openSync(fileUri);\\n        // 打开目标文件（创建或读写）\\n        let dstFile = fs.openSync(cacheFilePath, fs.OpenMode.READ_WRITE | fs.OpenMode.CREATE);\\n        // 复制文件内容\\n        fs.copyFileSync(srcFile.fd, dstFile.fd);\\n        // 关闭源文件\\n        fs.closeSync(srcFile);\\n        // 关闭目标文件\\n        fs.closeSync(dstFile);\\n      } catch (e) {\\n        console.info(`copy file failed ${e.message}`);\\n        return;\\n      }\\n\\n      // 使用默认实例上传文件至云存储\\n      this.bucket.uploadFile(getContext(this), {\\n        // 本地文件路径，位于context.cacheDir目录下\\n        localPath: cacheFile,\\n        // 云端存储路径\\n        cloudPath: fileName\\n      }).then((task: request.agent.Task) => {\\n        // 监听任务进度\\n        task.on(\'progress\', (progress) => {\\n          console.info(`on progress ${JSON.stringify(progress)}`);\\n        });\\n        // 监听任务完成\\n        task.on(\'completed\', (progress) => {\\n          console.info(`on completed ${JSON.stringify(progress)}`);\\n        });\\n        // 监听任务失败\\n        task.on(\'failed\', (progress) => {\\n          console.error(`on failed ${JSON.stringify(progress)}`);\\n        });\\n        // 监听任务响应\\n        task.on(\'response\', (response) => {\\n          console.info(`on response ${JSON.stringify(response)}`);\\n        });\\n\\n        // 启动任务，并处理启动结果\\n        task.start((err: BusinessError) => {\\n          if (err) {\\n            console.error(`Failed to start the uploadFile task, Code: ${err.code}, message: ${err.message}`);\\n          } else {\\n            console.info(`Succeeded in starting a uploadFile task.`);\\n          }\\n        });\\n      }).catch((err: BusinessError) => {\\n        console.error(`uploadFile failed, Code: ${err.code}, message: ${err.message}`);\\n      });\\n    })\\n}\\n\\n      Button(\\"计算8 上传文件到云端\\")\\n        .onClick(this.fn8)\\n\\n```\\n\\n**刷新AGC-中的云存储：**  可以看到文件成功上传了。\\n\\n![image-20250118235504943](assets/image-20250118235504943.png)\\n\\n### 查看云端文件列表\\n\\n如果想要获取云端文件列表，可以使用 **StorageBucket.list** API。\\n\\n#### 参数\\n\\n| 参数名    | 类型                                                         | 必填 | 说明                 |\\n| :-------- | :----------------------------------------------------------- | :--- | :------------------- |\\n| cloudPath | string                                                       | 是   | 云侧文件路径。       |\\n| options   | [ListOptions](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/cloudfoundation-cloudstorage-V5#section7984102813013) | 否   | 列举操作的相关参数。 |\\n\\n**ListOptions**\\n\\n| 名称       | 类型   | 只读 | 可选 | 说明                                                     |\\n| :--------- | :----- | :--- | :--- | :------------------------------------------------------- |\\n| maxResults | number | 否   | 是   | 列举文件的最大数量，取值范围1-1000，默认则列举所有文件。 |\\n| pageMarker | string | 否   | 是   | 分页标识。                                               |\\n\\n#### 返回内容\\n\\n| 名称        | 类型     | 只读 | 可选 | 说明                         |\\n| :---------- | :------- | :--- | :--- | :--------------------------- |\\n| directories | string[] | 否   | 否   | 列举操作返回的云侧目录列表。 |\\n| files       | string[] | 否   | 否   | 列举操作返回的云侧文件列表。 |\\n| pageMarker  | string   | 否   | 是   | 分页标识。                   |\\n\\n#### **示例代码**\\n\\n```typescript\\n  fn9 = async () => {\\n    try {\\n      const res = await this.bucket.list(\'\') // 获取根据根路径\\n      // const res = await this.bucket.list(\'avatar/\') // 获取 avatar/ 路径下的文件。 需要注意的是 如果你输入的路径是 ava ,那么 avatar也会被匹配到\\n      AlertDialog.show({ message: JSON.stringify(res, null, 2) })\\n    } catch (e) {\\n      promptAction.showToast({ message: `${e.message} ${e.code}` })\\n    }\\n  }\\n\\n    Button(\\"计算9 获取云端文件列表\\")\\n    .onClick(this.fn9)\\n```\\n\\n#### **得到结果**\\n\\n![image-20250119000030512](assets/image-20250119000030512.png)\\n\\n### 查看云端文件元数据\\n\\n我们可以通过该[StorageBucket.getMetadata](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/cloudfoundation-cloudstorage-V5#section2031534817364)API获取到文件名、文件大小、文件类型等常用属性，也包括用户自定义的文件属性。\\n\\n#### 参数\\n\\n| 参数名    | 类型   | 必填 | 说明           |\\n| :-------- | :----- | :--- | :------------- |\\n| cloudPath | string | 是   | 云侧文件路径。 |\\n\\n#### 返回值\\n\\n| 类型                                                         | 说明                                    |\\n| :----------------------------------------------------------- | :-------------------------------------- |\\n| Promise<[Metadata](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/cloudfoundation-cloudstorage-V5#section3472335144212)> | Promise对象，返回云侧文件的元数据信息。 |\\n\\n#### 示例代码\\n\\n```typescript\\n  fn10 = async () => {\\n    try {\\n      const res = await this.bucket.list(\'\')\\n      const cloudFilePath = res.files[0] // 获取第一个文件 -  实际开发中，你需要明确该路径下一定存在文件\\n      const res2 = await this.bucket.getMetadata(cloudFilePath)\\n      AlertDialog.show({ message: JSON.stringify(res2, null, 2) })\\n    } catch (e) {\\n      promptAction.showToast({ message: `${e.message} ${e.code}` })\\n    }\\n  }\\n\\nButton(\\"计算10 查看云端文件元数据\\")\\n.onClick(this.fn10)\\n```\\n\\n#### 得到结果\\n\\n![image-20250119001021913](assets/image-20250119001021913.png)\\n\\n### 获取云端文件下载地址\\n\\n我们之前通过`getMetadata`获取到了云端文件的相关信息。但是如果该文件是图片，而我们想要使用Image显示该图片，那么还需要使用[StorageBucket.getDownloadURL](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/cloudfoundation-cloudstorage-V5#section9969145143317)获取到该文件的下载地址。\\n\\n#### 参数\\n\\n| 参数名    | 类型   | 必填 | 说明           |\\n| :-------- | :----- | :--- | :------------- |\\n| cloudPath | string | 是   | 云侧文件路径。 |\\n\\n#### 返回值\\n\\n| `类型`            | `说明`                              |\\n| :---------------- | :---------------------------------- |\\n| `Promise<string>` | Promise对象，返回云侧文件下载地址。 |\\n\\n#### 示例代码\\n\\n```jsx\\n  fn11 = async () => {\\n    try {\\n      const res = await this.bucket.list(\'\')\\n      const cloudFilePath = res.files[0] // 获取第一个文件 -  实际开发中，你需要明确该路径下一定存在文件\\n      const res2 = await this.bucket.getDownloadURL(cloudFilePath)\\n      AlertDialog.show({ message: JSON.stringify(res2, null, 2) })\\n    } catch (e) {\\n      promptAction.showToast({ message: `${e.message} ${e.code}` })\\n    }\\n  }\\n\\nButton(\\"计算11 获取云端文件下载地址\\")\\n.onClick(this.fn11)\\n```\\n\\n#### 得到结果\\n\\n![image-20250119021913620](assets/image-20250119021913620.png)\\n\\n### 下载云端文件到本地\\n\\n利用 [StorageBucket.downloadFile](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/cloudfoundation-cloudstorage-V5#section02263293319)  可以将文件下载到 `ontext.cacheDir` 目录下。\\n\\n#### 参数\\n\\n| 参数名     | 类型                                                         | 必填 | 说明           |\\n| :--------- | :----------------------------------------------------------- | :--- | :------------- |\\n| context    | common.[BaseContext](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/js-apis-inner-application-basecontext-V5) | 是   | 应用上下文。   |\\n| parameters | [DownloadParams](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/cloudfoundation-cloudstorage-V5#section14137913019) | 是   | 下载相关参数。 |\\n\\n**DownloadParams**\\n\\n| 名称      | 类型                                                         | 只读 | 可选 | 说明                                                         |\\n| :-------- | :----------------------------------------------------------- | :--- | :--- | :----------------------------------------------------------- |\\n| localPath | string                                                       | 否   | 否   | 本地文件路径，根路径为cache目录。                            |\\n| cloudPath | string                                                       | 否   | 否   | 云侧文件路径。                                               |\\n| mode      | [request.agent.Mode](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/js-apis-request-V5#mode10) | 否   | 是   | 下载任务类型，前端任务在应用切换到后台一段时间后失败/暂停；后台任务不受影响。默认为BACKGROUND。BACKGROUND：后台任务。FOREGROUND：前端任务。 |\\n| overwrite | boolean                                                      | 否   | 是   | 当本地文件已存在时，是否覆盖本地文件，默认false。true：覆盖本地文件。false：不覆盖，若存在同名文件则下载失败。 |\\n| network   | [request.agent.Network](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/js-apis-request-V5#network10) | 否   | 是   | 下载任务的网络配置，网络不满足设置条件时，未执行的任务等待执行，执行中的任务失败/暂停。默认为ANY。ANY：不限网络类型。WIFI：无线网络。CELLULAR：蜂窝数据网络。 |\\n\\n#### 返回值\\n\\n| 类型              | 说明                        |\\n| :---------------- | :-------------------------- |\\n| `Promise<[Task]>` | Promise对象，返回下载任务。 |\\n\\n#### 示例代码\\n\\n```jsx\\n  fn12 = async () => {\\n    try {\\n      const res = await this.bucket.list(\'\')\\n      const cloudFilePath = res.files[0] // 获取第一个文件 -  实际开发中，你需要明确该路径下一定存在文件\\n      const task = await this.bucket.downloadFile(getContext(this), {\\n        localPath: Date.now().toString(), // 本地文件路径, 下载成功后，文件将会保存在context.cacheDir目录\\n        cloudPath: cloudFilePath  // 云侧文件路径\\n      })\\n      task.on(\'progress\', (progress) => {\\n        console.info(`on progress ${JSON.stringify(progress)} `);\\n      });\\n      task.on(\'completed\', (progress) => {\\n        console.info(`on completed ${JSON.stringify(progress)} `);\\n        AlertDialog.show({ message: JSON.stringify(\\"下载完成\\", null, 2) })\\n      });\\n      task.on(\'failed\', (progress) => {\\n        console.error(`on failed ${JSON.stringify(progress)} `);\\n      });\\n      task.on(\'response\', (response) => {\\n        console.info(`on response ${JSON.stringify(response)} `);\\n      });\\n      task.start((err: BusinessError) => {\\n        if (err) {\\n          console.error(`Failed to start the downloadFile task, Code: ${err.code}, message: ${err.message}`);\\n        } else {\\n          console.info(`Succeeded in starting a downloadFile task. result: ${task.tid}`);\\n        }\\n      });\\n    } catch (e) {\\n      promptAction.showToast({ message: `${e.message} ${e.code}` })\\n    }\\n  }\\n\\n\\n  Button(\\"计算12 下载云端文件\\")\\n    .onClick(this.fn12)\\n```\\n\\n#### 得到结果\\n\\n![image-20250119022910282](assets/image-20250119022910282.png)\\n\\n### 删除云端文件\\n\\n调用[StorageBucket.deleteFile](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/cloudfoundation-cloudstorage-V5#section1290422653419)删除云侧的文件。\\n\\n#### 参数\\n\\n| 参数名    | 类型   | 必填 | 说明           |\\n| :-------- | :----- | :--- | :------------- |\\n| cloudPath | string | 是   | 云侧文件路径。 |\\n\\n#### 返回值\\n\\n| 类型            | 说明                                   |\\n| :-------------- | :------------------------------------- |\\n| `Promise<void>` | Promise对象。无返回结果的Promise对象。 |\\n\\n#### 示例代码\\n\\n```\\n  fn13 = async () => {\\n    try {\\n      const res = await this.bucket.list(\'\')\\n      const cloudFilePath = res.files[0] // 获取第一个文件 -  实际开发中，你需要明确该路径下一定存在文件\\n      await this.bucket.deleteFile(cloudFilePath)\\n      promptAction.showToast({ message: `${\\"成功\\"}` })\\n    } catch (e) {\\n      promptAction.showToast({ message: `${e.message} ${e.code}` })\\n    }\\n  }\\n```\\n\\n#### 得到结果\\n\\n![image-20250119023215094](assets/image-20250119023215094.png)\\n\\n---\\n\\n## 云函数开发\\n\\n之前的文章中把云数据库、云存储都讲过了，这一章节要讲解的是**云函数**。\\n\\n### 云函数介绍\\n\\n云函数其实就是serverless技术。可以理解云函数就实现传统后端中的具体业务，而无需关心服务器购买、部署、安全、性能等一系列相关问题，专注于具体的业务开发。HarmonyOS Next的云函数采用的是typescript的语法，这对熟悉js或者熟悉ArkTs的同学来说都很容易上手。\\n\\n另外云函数具有调用其他云函数、调用第三方接口、调用云存储、调用云数据库的能力。对于段云一体化开发的应用来说，可以根据这样的场景来使用云函数。\\n\\n1. 简单的数据库查询、云端文件的管理可以直接使用客户端操作的方式。\\n2. 繁琐或者涉及安全的操作，可以把业务抽离到云函数端，这样更加容易管理项目。\\n\\n本章节也会讲解如何云函数的开发、创建、调试、部署，以及在云函数端调用其他云函数、调用第三方接口、调用云存储、调用云数据库。\\n\\n### 创建云函数\\n\\n可以选择创建云函数或者云对象。这里建议选择云对象更加方便业务逻辑的实现。为什么呢，举个例子。书籍的crud刚好放在一个对象中，增、删、改、查都可以做个一个对象的属性存在，更加容易方便管理。比如以下示例。\\n\\n- 云函数一览\\n\\n  ```typescript\\n  // 云函数\\n  let myHandler = async function (event, context, callback, logger) {\\n    //   这里写不同的业务逻辑，都是都耦合在一个myHandler中\\n    callback();\\n  };\\n\\n  export { myHandler }\\n  ```\\n\\n- 云对象一览\\n\\n  ```typescript\\n  export class Book {\\n    //   增加\\n    add() {\\n      return {};\\n    }\\n\\n    //   删除\\n    delete() {\\n    }\\n\\n    //   修改\\n    update() {\\n    }\\n\\n    //   查询\\n    query() {\\n    }\\n  }\\n  ```\\n\\n新建云对象，云对象名称为book。\\n\\n![image-20250208224404854](assets/image-20250208224404854.png)\\n\\n得到以下新文件，其中 `book.ts` 是编写云对象book具体业务逻辑的。`function-config.json`是关于该云对象的相关配置如是否鉴权等。`package.json`是该云对象的描述文件，具体作用类似 `oh-package.json`,后续安装第三方依赖也会在这里登记信息。\\n\\n![image-20250208225612809](assets/image-20250208225612809.png)\\n\\n#### function-config.json\\n\\n文件内容如下。\\n\\n```json\\n{\\n  \\"handler\\": \\"book.Book\\",\\n  \\"functionType\\": 1,\\n  \\"triggers\\": [\\n    {\\n      \\"type\\": \\"http\\",\\n      \\"properties\\": {\\n        \\"enableUrlDecode\\": true,\\n        \\"authFlag\\": \\"true\\",\\n        \\"authAlgor\\": \\"HDA-SYSTEM\\",\\n        \\"authType\\": \\"apigw-client\\"\\n      }\\n    }\\n  ]\\n}\\n```\\n\\n相关解析如下\\n\\n- handler 表示云对象的入口\\n\\n- functionType 表示函数类型，\\"0\\"表示云函数，\\"1\\"表示云对象。\\"functionType\\"的值为创建时自动生成，不可手动修改，否则将导致云函数部署失败。\\n\\n- triggers 表示触发云对象的函数\\n\\n  - type：触发器类型，配置为\\"http\\"。\\n\\n  - properties：触发器属性，属性参数如下表所示。\\n\\n    | 参数            | 说明                                                         |\\n    | :-------------- | :----------------------------------------------------------- |\\n    | enableUrlDecode | 通过HTTP触发器触发函数时，对于contentType为\\"application/x-www-form-urlencoded\\"的触发请求，是否使用URLDecoder对请求body进行解码再转发到函数中。true：启用。false：不启用。 |\\n    | authFlag        | 是否鉴权，默认为true。                                       |\\n    | authAlgor       | 鉴权算法，默认为HDA-SYSTEM。                                 |\\n    | authType        | HTTP触发器的认证类型。apigw-client：端侧网关认证，适用于来自APP客户端侧（即本地应用或者项目）的函数调用。cloudgw-client：云侧网关认证，适用于来自APP服务器侧（即云函数）的函数调用。 |\\n\\n#### oh-package.json\\n\\n文件内容如下。\\n\\n```json\\n{\\n  \\"name\\": \\"book\\",\\n  \\"version\\": \\"1.0.0\\",\\n  \\"description\\": \\"\\",\\n  \\"scripts\\": {\\n    \\"test\\": \\"echo \\\\\\"Error: no test specified\\\\\\" && exit 1\\"\\n  },\\n  \\"author\\": \\"\\",\\n  \\"license\\": \\"ISC\\",\\n  \\"dependencies\\": {\\n  }\\n}\\n```\\n\\n相关解释如下。\\n\\n- **`name`**：表示项目的名称\\n- **`version`**：项目的版本号\\n- **`description`**：项目的描述\\n- **`scripts`**：一个包含各种脚本命令的对象\\n- **`author`**：项目作者信息\\n- **`license`**：项目所使用的开源许可证，这里是 `\\"ISC\\"`\\n- **`dependencies`**：项目的依赖信息\\n\\n#### book.ts\\n\\nbook.ts的文件解析如下。\\n\\n1. **methods1**表示云对象具体的方法，可以有多个。\\n2. **params1**、**params2**是传递给该云对象的参数\\n3. **return** 的内容是返回给云对象的调用者\\n\\n![image-20250208224438567](assets/image-20250208224438567.png)\\n\\n### 调试云函数/对象\\n\\n在开发云对象时，经常需要编写繁琐的业务逻辑，那么就必不可少对象的调试。DevEco Studio 内置了云对象的调试面板。按照以下步骤操作就可以方便对云对象进行调试了。\\n\\n1. 启动云对象调试，鼠标右键你要调试的云对象、选择 **Debug \'book\'**\\n\\n   ![image-20250208225401478](assets/image-20250208225401478.png)\\n\\n2. 打开云对象调试面板\\n\\n   ![image-20250208231342642](assets/image-20250208231342642.png)\\n\\n3. 云对象日志面板\\n\\n   当我们在云对象中使用console.log调试代码时，日志的输出在这个位置。\\n\\n   ![image-20250208231411534](assets/image-20250208231411534.png)\\n\\n需要注意的是当我们修改了云对象的代码时，都需要重新点击 **debug book**\\n\\n![image-20250208231500267](assets/image-20250208231500267.png)\\n\\n### 部署云对象\\n\\n当云对象开发完毕后，想要客户端调用或者上线生产环境，都需要部署上去。右键你的云对象，选择 **Deploy \'book\'**  就可以把你的云对象部署到云端了。你也可以鼠标右键 **cloudfouctions** 部署或者同步所有的云对象。\\n\\n> 如果想要把之前部署到云端的云对象下载下来，选择 **Sync book**  即可\\n\\n![image-20250209095250827](assets/image-20250209095250827.png)\\n\\n部署成功，右下角会有相应的提示。\\n\\n![image-20250209095502324](assets/image-20250209095502324.png)\\n\\n### 客户端调用云对象\\n\\n当我们创建好了云对象后，就可以使用客户端直接调用云对象的方法了。\\n\\n如果是客户端调用云函数，可以参考以下代码。\\n\\n核心代码如下。\\n\\n```typescript\\ntry {\\n  const res = await cloudFunction.call({\\n    // 云对象的名称，这个和你创建的云对象文件名一致\\n    name: \\"book\\",\\n    data: {\\n      // book云对象的methods1方法\\n      method: \'method1\',\\n      // 传递给method1的参数\\n      params: [\'a\', \'b\'],\\n    }\\n  })\\n  AlertDialog.show({ message: JSON.stringify(res, null, 2) })\\n} catch (e) {\\n  console.error(e.message + \\" \\" + e.code)\\n}\\n```\\n\\n这里重点讲解的是**客户端调用云对象**。\\n\\nDevEco Studio 提供了方便的方式实现客户端调用云对象的功能。可以让我们想调用普通对象方法一样，直接调用云对象！\\n\\n具体操作步骤如下。\\n\\n1. 依据云对象 ，在客户端生成云对象的调用模型。  鼠标右键你的云对象 Book。选择 **Generate Invoke Interface**\\n\\n   ![image-20250209104450026](assets/image-20250209104450026.png)\\n\\n2. 选择存放该模型文件的路径\\n\\n   ![image-20250209104513583](assets/image-20250209104513583.png)\\n\\n3. 生成成功后，得到两个关键文件 `ImportObject.ts` 和 `Book.ets`\\n\\n   ![image-20250209104549805](assets/image-20250209104549805.png)\\n\\n   `ImportObject.ts`文件的主要作用是利用代理Proxy的方式，当用户调用`Book.method1` 方法时，在内部执行了 云函数的调用方法`cloudFunction.call`方法。为我们调用云对象提供了便利。代码如下。\\n\\n   ```typescript\\n   /*\\n    * Copyright (c) Huawei Technologies Co., Ltd. 2020-2024. All rights reserved.\\n    * Generated by the Cloud Object compiler. DO NOT EDIT!\\n    */\\n   import type { BusinessError } from \'@kit.BasicServicesKit\';\\n   import { cloudFunction } from \'@kit.CloudFoundationKit\';\\n\\n   export interface CloudObjectLikely {\\n     name: string;\\n   }\\n\\n   function mockMethod<T extends CloudObjectLikely>(target: T, version: string,\\n     prop: string | symbol): (...args: unknown[]) => Promise<unknown> {\\n     return async (...args: unknown[]) => new Promise((resolve, reject) => {\\n       cloudFunction.call({\\n         name: target.name,\\n         version: version,\\n         data: {\\n           method: prop,\\n           params: args\\n         }\\n       }).then((value: cloudFunction.FunctionResult) => {\\n         resolve(value.result);\\n       }).catch((err: BusinessError) => {\\n         reject(err);\\n       });\\n     });\\n   }\\n\\n   export function importObject<T extends CloudObjectLikely>(tClass: new () => T, version = \'$latest\'): T {\\n     return new Proxy<T>(new tClass(), {\\n       get(target, prop): (...args: unknown[]) => Promise<unknown> {\\n         return mockMethod<T>(target, version, prop);\\n       }\\n     });\\n   }\\n\\n   ```\\n\\n   `Book.ets`文件的作用是参考云对象Book的模型，生成对应的类，方便我们调用云对象。代码如下。\\n\\n   ```typescript\\n   /*\\n    * Copyright (c) Huawei Technologies Co., Ltd. 2020-2024. All rights reserved.\\n    * Generated by the Cloud Object compiler. DO NOT EDIT!\\n    */\\n   import type { CloudObjectLikely } from \'../ImportObject\';\\n\\n   export class Book implements CloudObjectLikely {\\n       public name = \'book\';\\n       public async method1(param1: any, param2: any): Promise<{\\n           simple: string;\\n           param1: any;\\n           param2: any;\\n       }> {\\n\\n           return Promise.reject(new Error(\'Method not implemented.\'));\\n       }\\n   }\\n   ```\\n\\n4. 最后，在客户端中需要导入 `Book` 和 `importObject`，再进行调用\\n\\n   ```jsx\\n   // 这里需要对Book进行重命名，因为和之前的数据库类型Book重名了\\n   import { Book as BookCloudObj } from \'../cloudobject/book/Book\';\\n   import { importObject } from \'../cloudobject/ImportObject\';\\n\\n         Button(\\"调用云对象14的方法\\")\\n           .onClick(this.fn14)\\n\\n       fn14 = async () => {\\n       try {\\n         let bookObj = importObject(BookCloudObj); // 使用importObject实例化BookCloudObj的代理\\n         const res = await bookObj.method1(\'100\', \'200\')\\n         AlertDialog.show({ message: JSON.stringify(res, null, 2) })\\n       } catch (e) {\\n         console.error(e.message + \\" \\" + e.code)\\n       }\\n     }\\n   ```\\n\\n5. 调用结果如图。\\n\\n   ![image-20250209105304376](assets/image-20250209105304376.png)\\n\\n### 云对象调用云对象\\n\\n在实际开发中，一般情况下，某个具体的业务是存在某个具体的云对象中的，但是必不可少的会出现业务之间的关联。比如查询某一个作者编写过的所有的书籍。作者可以是一个单独的云对象，书籍也是一个单独的云对象，这样就会出现云对象之间调用云对象 需求。我们可以通过 book云对象调用auth云对象来演示。\\n\\n> 由于云对象部署到云端后是各自独立的，因此这里不能简单的将多个云对象看成是同一个目录之间的关系，也就是不能 云对象a使用相对路径直接导入云对象b ！\\n\\n1. 新建auth云对象 *这个看上面的创建book云对象步骤即可*\\n\\n2. 调整auth云对象的网关设置\\n\\n   `function-config.json` 中的**authType**设置为 `cloudgw-client`\\n\\n   ```json\\n   \\"authType\\": \\"cloudgw-client\\"\\n   ```\\n\\n3. 编写auth云对象逻辑代码\\n\\n   ```js\\n   export class Auth {\\n     getName(firstName, lastName) {\\n       return { firstName, lastName, fullName: firstName + lastName };\\n     }\\n   }\\n   ```\\n\\n4. book安装云对象三方库，注意需要在book云对象目录下安装\\n\\n   ```sh\\n   npm install @hw-agconnect/cloud-server\\n   ```\\n\\n   ![image-20250209112440351](assets/image-20250209112440351.png)\\n\\n5. book调用auth云对象\\n\\n   ```js\\n   import { cloud } from \\"@hw-agconnect/cloud-server\\";\\n\\n   export class Book {\\n     async method1(param1, param2) {\\n\\n       const res = await cloud.function().call({\\n         // 云对象的名称\\n         name: \\"auth\\",\\n\\n         data: {\\n           // 云对象的方法\\n           method: \\"getName\\",\\n           // 传递的参数\\n           params: [\'万\', \\"大妈\\"]\\n         }\\n       });\\n\\n       return {\\n         \\"simple\\": \\"example\\",\\n         param1,\\n         param2,\\n         res\\n       };\\n     }\\n   }\\n   ```\\n\\n6. auth和book都部署到云端\\n\\n7. 客户端测试调用，验证效果\\n\\n   ![image-20250209112607971](assets/image-20250209112607971.png)\\n\\n   支持，便完成了云对象调用云对象了。\\n\\n### 云对象调用云存储\\n\\n在翻阅了相关文档后，发现云对象对于云存储的支持程度远不够，这里略过。\\n\\n### 云对象调用云数据库\\n\\n云对象中也是需要引入 `@hw-agconnect/cloud-server` 来操作云数据库的。我们按照以下步骤进行操作。实现查询云对象中查询数据库的功能。\\n\\n1. 首先在云对象book处新建一个文件夹model，用来存放即将生成的文件\\n\\n   ![image-20250209133623676](assets/image-20250209133623676.png)\\n\\n2. 在云端生成操作Book表格的云对象模块。这里 DevEco Studio会自动帮我们生成。选择**Generate Server Model**。\\n\\n   ![image-20250209133103645](assets/image-20250209133103645.png)\\n\\n   然后选择生成的路径。\\n\\n   ![image-20250209133521557](assets/image-20250209133521557.png)\\n\\n3. 得到文件 `model/book.ts` ,这里为了和之前的`book.ts`区分，我们把它名称修改成 `model/bookModel.ts`。文件中的类名也修改成 `BookModel`\\n\\n   ```typescript\\n   /*\\n    * Copyright (c) Huawei Technologies Co., Ltd. 2020-2023. All rights reserved.\\n    * Generated by the CloudDB ObjectType compiler. DO NOT EDIT!\\n    */\\n\\n   class BookModel {\\n     id: number;\\n     name: string;\\n     price: number;\\n     publish: Date;\\n     hot: boolean;\\n     cover: string;\\n\\n     constructor() {\\n     }\\n\\n     getFieldTypeMap(): Map<string, string> {\\n       let fieldTypeMap = new Map<string, string>();\\n       fieldTypeMap.set(\'id\', \'Integer\');\\n       fieldTypeMap.set(\'name\', \'String\');\\n       fieldTypeMap.set(\'price\', \'Double\');\\n       fieldTypeMap.set(\'publish\', \'Date\');\\n       fieldTypeMap.set(\'hot\', \'Boolean\');\\n       fieldTypeMap.set(\'cover\', \'String\');\\n       return fieldTypeMap;\\n     }\\n\\n     getClassName(): string {\\n       return \'Book\';\\n     }\\n\\n     getPrimaryKeyList(): string[] {\\n       let primaryKeyList: string[] = [];\\n       primaryKeyList.push(\'id\');\\n       return primaryKeyList;\\n     }\\n\\n     getIndexList(): string[] {\\n       let indexList: string[] = [];\\n       indexList.push(\'id\');\\n       indexList.push(\'price\');\\n       return indexList;\\n     }\\n\\n     getEncryptedFieldList(): string[] {\\n       let encryptedFieldList: string[] = [];\\n       return encryptedFieldList;\\n     }\\n\\n     setId(id: number): void {\\n       this.id = id;\\n     }\\n\\n     getId(): number {\\n       return this.id;\\n     }\\n\\n     setName(name: string): void {\\n       this.name = name;\\n     }\\n\\n     getName(): string {\\n       return this.name;\\n     }\\n\\n     setPrice(price: number): void {\\n       this.price = price;\\n     }\\n\\n     getPrice(): number {\\n       return this.price;\\n     }\\n\\n     setPublish(publish: Date): void {\\n       this.publish = publish;\\n     }\\n\\n     getPublish(): Date {\\n       return this.publish;\\n     }\\n\\n     setHot(hot: boolean): void {\\n       this.hot = hot;\\n     }\\n\\n     getHot(): boolean {\\n       return this.hot;\\n     }\\n\\n     setCover(cover: string): void {\\n       this.cover = cover;\\n     }\\n\\n     getCover(): string {\\n       return this.cover;\\n     }\\n\\n     static parseFrom(inputObject: any): BookModel {\\n       let result = new BookModel();\\n       if (!inputObject) {\\n         return result;\\n       }\\n       if (inputObject.id) {\\n         result.id = inputObject.id;\\n       }\\n       if (inputObject.name) {\\n         result.name = inputObject.name;\\n       }\\n       if (inputObject.price) {\\n         result.price = inputObject.price;\\n       }\\n       if (inputObject.publish) {\\n         result.publish = new Date(inputObject.publish);\\n       }\\n       if (inputObject.hot) {\\n         result.hot = inputObject.hot;\\n       }\\n       if (inputObject.cover) {\\n         result.cover = inputObject.cover;\\n       }\\n       return result;\\n     }\\n   }\\n\\n   export { BookModel };\\n   ```\\n\\n4. 新建文件`bookController.ts`，负责组合 对book实例的CURD操作。\\n\\n   ```typescript\\n   import { cloud, CloudDBCollection } from \'@hw-agconnect/cloud-server\'; //引入Server SDK依赖\\n   import { BookModel } from \'./model/BookModel\'; //BookModel为对象类型名\\n\\n   // ZONE_NAME为存储区名称\\n   const ZONE_NAME = \\"Study\\";\\n\\n   export class BookCtroller {\\n     collection: CloudDBCollection<BookModel>;\\n\\n     constructor() {\\n       this.collection = cloud.database({ zoneName: ZONE_NAME }).collection(BookModel);\\n     }\\n\\n     //查询数据\\n     async queryBooks() {\\n       let query = this.collection.query();\\n       return await query.get();\\n     }\\n\\n     //更新数据\\n     async upsertBooks(records: BookModel[]) {\\n       return await this.collection.upsert(records);\\n     }\\n\\n     //删除数据\\n     async deleteBooks(records: BookModel[]) {\\n       return await this.collection.delete(records);\\n     }\\n   }\\n   ```\\n\\n5. 最后在云对象book中添加一个查询方法 query。\\n\\n   ```typescript\\n     // 查询数据库\\n     async query() {\\n       let bookCtroller = new BookCtroller();\\n       const result = await bookCtroller.queryBooks()\\n       return {\\n         result\\n       }\\n     }\\n   ```\\n\\n6. 测试调用\\n\\n   ![image-20250209140233851](assets/image-20250209140233851.png)\\n\\n其他的数据库操作可以基于该模式进行拓展。\\n\\n### 云对象调用第三方api\\n\\n如想要调用其他的api，比较简单的方式可以直接安装axios，然后像调用接口一样使用axios即可。\\n\\n---\\n\\n## 总结\\n\\n本文完整介绍了HarmonyOS Next端云一体化开发的各个方面，包括：\\n\\n### 端云一体化基础\\n- Cloud Foundation Kit的基本概念和应用场景\\n- AGC平台和DevEco Studio的环境搭建\\n- 云函数、云数据库、云存储三大核心资源\\n\\n### 云数据库操作\\n- 存储区和对象类型的创建与配置\\n- 对象类型的规范（objectTypeName、fields、indexes、permissions）\\n- 数据条目的添加和部署流程\\n\\n### 客户端操作云数据库\\n- 四种操作方式的对比\\n- 客户端数据模型的自动生成\\n- 基本CRUD操作：query、upsert、delete、calculateQuery\\n\\n### 数据库查询条件\\n- 谓词的概念和使用\\n- 丰富的查询条件：比较、字符串匹配、逻辑组合等\\n- 实际应用示例\\n\\n### 云存储操作\\n- 云存储的计费策略\\n- 核心功能：上传、下载、列表、元数据、删除\\n- 文件操作的完整流程\\n\\n### 云函数开发\\n- 云函数vs云对象的对比\\n- 云对象的创建、调试、部署\\n- 客户端调用云对象的方式\\n- 云对象之间的相互调用\\n- 云对象操作云数据库\\n\\n通过本教程的学习，开发者可以全面掌握HarmonyOS Next端云一体化开发的核心技术，为构建高效、安全的应用提供完整的解决方案。\\n\\n---\\n\\n## 参考文档\\n\\n1. [云侧通过SDK使用云数据库](https://developer.huawei.com/consumer/cn/doc/AppGallery-connect-Guides/agc-clouddb-via-sdk-server-0000001569149001)\\n2. [@hw-agconnect/cloud-server](https://www.npmjs.com/package/@hw-agconnect/cloud-server#cloud-functions)\\n3. [端云一体化开发](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/agc-harmonyos-clouddevguide-V5)\\n\\n如果你兴趣想要了解更多的鸿蒙应用开发细节和最新资讯，欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。"}'),ts={name:"鸿蒙开发技巧/HarmonyOSNext 端云一体化/HarmonyOSNext 端云一体化完整版/HarmonyOSNext 端云一体化完整版.md"};function ls(es,s,ps,hs,ks,rs){return a(),n("div",null,[...s[0]||(s[0]=[t("",379)])])}const os=i(ts,[["render",ls]]);export{Es as __pageData,os as default};
